% Initialize the potential matrix
u = zeros(size(X));

% Number of terms to include in the series
num_terms = 5;

% Sum the series
for n = 1:num_terms
    if mod(n, 2) == 1 % Only include odd terms
        term = (50 * cos((n * pi * X) / 3) - 50 * cot((n * pi) / 3) * sin((n * pi * X) / 3)) ...
               * (200 / (n * pi)) * sin((n * pi * Y) / 3);
        u = u + term;
    end
end

% Plot the potential distribution
figure;
surf(X, Y, u);
shading interp;
colorbar;
