U = K \ F;

% Plot the solution
figure;
trisurf(t, p(:, 1), p(:, 2), U, 'FaceColor', 'interp');
shading interp;
colorbar;
xlabel('x (m)');
ylabel('y (m)');
zlabel('Potential (V)');
title('Potential Distribution in a 1m x 3m Rectangular Domain');

% Check the value at (1, 1)
