u(1, :) = 0;
u(end, :) = 0;

% Coefficient for the Crank-Nicolson method
r = alpha * dt / (2 * dx^2);

% Precompute the tridiagonal matrix for the Crank-Nicolson method
A = spdiags([ones(Nx-2, 1) -2*ones(Nx-2, 1) ones(Nx-2, 1)], [-1 0 1], Nx-2, Nx-2);
B = spdiags([-r*ones(Nx-2, 1) (1 + 2*r)*ones(Nx-2, 1) -r*ones(Nx-2, 1)], [-1 0 1], Nx-2, Nx-2);

