% Objective function to minimize
objective_function = @(C) sum_of_squared_errors(C, initial_guess, data_points, L, k, T_final, Nx, Nt);

% Use an optimization algorithm to find the best initial condition
options = optimoptions('fminsearch', 'Display', 'iter');
best_C = fminsearch(objective_function, 0, options);

% Define the optimized initial condition
