    for i = 2:Nx-1
        u(i, n+1) = u(i, n) + alpha * (u(i+1, n) - 2*u(i, n) + u(i-1, n));
    end
end

% Check the measured data points
for i = 1:size(data_points, 1)
    x_idx = round(data_points(i, 1) / dx) + 1;
    t_idx = round(data_points(i, 2) / dt) + 1;
