dx = L / (Nx - 1); % Grid spacing (m)
dt = T_final / Nt; % Time step (s)

% Range of initial conditions
initial_conditions = @(x, C) 50 * sin(pi * x / 2) + C;
C_values = linspace(-5, 5, 10); % Range of C values

