% Initialize temperature array
u = zeros(Nx, Nt);
x = linspace(0, L, Nx);
u(:, 1) = initial_condition(x);

% Boundary conditions
u(1, :) = boundary_left((0:Nt-1)' * dt);
u(end, :) = boundary_right((0:Nt-1)' * dt);

% Time-stepping loop
for n = 1:Nt-1
    b = B * u(2:end-1, n)';
    b(1) = b(1) + alpha * u(1, n);
    b(end) = b(end) + alpha * u(end, n);
    u(2:end-1, n+1) = A \ b;
end

% Plot results
