    k = k_func(x);
    u(:, n) = u(:, n-1) + k * dt / dx^2 * (circshift(u(:, n-1), [0 1]) - 2*u(:, n-1) + circshift(u(:, n-1), [0 -1]));
end

% Find corresponding indices for experimental data points
x_idx = round(experimental_data(:, 1) / dx) + 1;
t_idx = round(experimental_data(:, 2) / dt) + 1;

