u_exp_smooth = smoothdata(u_exp_noisy, 'movmean', window_size);

% Median filtering for robust smoothing
u_exp_median = medfilt1(u_exp_noisy, [window_size]);

% Low-pass filtering
Fs = 1 / (x_exp(2) - x_exp(1)); % Sampling frequency
cutoff_freq = 0.1 * Fs; % Cutoff frequency
