u_exp_interpolated_lowpass = interp1(x_exp, u_exp_lowpass, x, 'linear');

% Calculate the error
error_movmean = abs(u(:, t_idx) - u_exp_interpolated_movmean);
error_median = abs(u(:, t_idx) - u_exp_interpolated_median);
