u(:, 1) = 100 * sin(pi * x); % Example initial condition

% Boundary conditions
u(1, :) = 0;
u(end, :) = 0;

% Coefficients for Crank-Nicolson method
r = k * dt / (2 * dx^2);
A = spdiags([ones(Nx-2, 1) * (-r), ones(Nx-2, 1) * (1 + 2*r), ones(Nx-2, 1) * (-r)], [-1, 0, 1], Nx-2, Nx-2);
B = spdiags([ones(Nx-2, 1) * r, ones(Nx-2, 1) * (1 - 2*r), ones(Nx-2, 1) * r], [-1, 0, 1], Nx-2, Nx-2);

% Solve the heat equation using Crank-Nicolson method
for n = 1:Nt-1
    b = B * u(2:end-1, n);
