% Solve the heat equation using finite differences
for n = 1:Nt-1
    u(2:end-1, 2:end-1, n+1) = u(2:end-1, 2:end-1, n) + ...
        alpha * (u(3:end, 2:end-1, n) - 2*u(2:end-1, 2:end-1, n) + u(1:end-2, 2:end-1, n) + ...
                 u(2:end-1, 3:end, n) - 2*u(2:end-1, 2:end-1, n) + u(2:end-1, 1:end-2, n));
