        best_solution = population(idx, :);
    end

    % Selection
    parents = population(sortrows([fitness_values, 1:pop_size], 1, 'ascend')(1:pop_size/2, 2), :);

    % Crossover
    children = [];
    for i = 1:2:pop_size-1
        child1 = parents(i, :) + 0.5 * (parents(i+1, :) - parents(i, :));
        child2 = parents(i+1, :) + 0.5 * (parents(i, :) - parents(i+1, :));
        children = [children; child1; child2];
    end

    % Mutation
    mutation_indices = rand(pop_size, 2) < mutation_rate;
    children(mutation_indices) = rand(size(children(mutation_indices)));

    % New population
    population = [parents; children];
end

% Best solution found
disp(['Best solution: ', num2str(best_solution)]);
disp(['Best fitness: ', num2str(best_fitness)]);

% Helper function to evaluate fitness
function fitness = evaluate_fitness(params, L, T, Nx, Nt, dx, dt, alpha)
    % Boundary conditions
    T1 = params(1);
    T2 = params(2);

    % Initialize temperature array
    u = zeros(Nx, Nt+1);
    x = linspace(0, L, Nx);

    % Initial condition
    u(:, 1) = 20 + 10 * sin(pi * x / L);

    % Boundary conditions
    u(1, :) = T1;
    u(end, :) = T2;

    % Solve heat equation using Crank-Nicolson method
    r = @(x, t) alpha(x, t) * dt / (2 * dx^2);
    A = spdiags([ones(Nx-1, 1) -2*ones(Nx, 1) ones(Nx-1, 1)], [-1 0 1], Nx, Nx);
    B = spdiags([ones(Nx-1, 1) 2*ones(Nx, 1) -ones(Nx-1, 1)], [-1 0 1], Nx, Nx);

    for n = 1:Nt
        t = (n-1) * dt;
        b = u(:, n) + r(x, t) .* (A * u(:, n) + B * u(:, n));
        u(:, n+1) = A \ b;

        % Apply boundary conditions
        u(1, n+1) = T1;
        u(end, n+1) = T2;
    end

    % Compute cost functional
    ur = diff(u, 1, 1) / dx; % Approximate radial derivative
    J = sum(sum(ur.^2 + u.^2, 1) .* dx, 2);
    fitness = J(end);
end
